#!/usr/bin/env node
/**
 * Generates a static og-image.png for social previews.
 * Renders an SVG composition to PNG via sharp; output at 1200x630.
 * Run via `npm run build:og` whenever the design changes. Impeccable checks
 * shipped rasters for provenance; after regenerating, re-embed the origin with
 * `impeccable embed-prompt public/og-image.png --prompt "Origin: generated by
 * scripts/generate-og.mjs (SVG rendered with sharp)."`.
 */
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const __dirname = dirname(fileURLToPath(import.meta.url));
const outDir = join(__dirname, '..', 'public');

const ink = '#ede8e1';
const ink2 = '#bdb5ab';
const ink3 = '#9a9187';
const accent = '#d97757';
const mono = "'JetBrains Mono', ui-monospace, Menlo, monospace";

// Six-armed asterisk: the same mark as public/favicon.svg.
const mark = (x, y, s) => `<g transform="translate(${x},${y}) scale(${s})" fill="${accent}">
    <rect x="-1.6" y="-11" width="3.2" height="22" rx="1.6"/>
    <rect x="-1.6" y="-11" width="3.2" height="22" rx="1.6" transform="rotate(60)"/>
    <rect x="-1.6" y="-11" width="3.2" height="22" rx="1.6" transform="rotate(120)"/>
  </g>`;

// The page's first viewport in miniature: the welcome box, the install
// command at a $ prompt, and the status line.
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630">
  <rect width="1200" height="630" fill="#1a1816"/>

  <rect x="80" y="70" width="1040" height="330" rx="22" fill="none" stroke="${accent}" stroke-width="2.5"/>
  ${mark(128, 128, 0.95)}
  <text x="152" y="137" font-family="${mono}" font-size="26" fill="${ink2}">Welcome to the Claude Code cheat sheet</text>
  <text x="120" y="250" font-family="${mono}" font-size="74" font-weight="700" fill="${ink}" letter-spacing="-2.5">Claude Code CLI,</text>
  <text x="120" y="335" font-family="${mono}" font-size="74" font-weight="700" fill="${ink}" letter-spacing="-2.5">on one page</text>

  <rect x="80" y="440" width="1040" height="72" rx="10" fill="#221f1c" stroke="#3b3631" stroke-width="2"/>
  <text x="112" y="486" font-family="${mono}" font-size="27" fill="${ink3}">$</text>
  <text x="146" y="486" font-family="${mono}" font-size="27" fill="${ink}">curl -fsSL https://claude.ai/install.sh | bash</text>

  <text x="96" y="566" font-family="${mono}" font-size="22" fill="${accent}">⏵⏵ auto mode</text>
  <text x="282" y="566" font-family="${mono}" font-size="22" fill="${ink3}">· commands · modes · CLAUDE.md · skills · plugins · MCP · hooks</text>
</svg>`;

const png = await sharp(Buffer.from(svg)).png().toBuffer();
const outPath = join(outDir, 'og-image.png');
writeFileSync(outPath, png);
console.log(`Wrote ${outPath} (${png.length} bytes)`);
